use std::fs

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let limit: int = 200000
    let mut sieve: Vec<bool> = []
    let mut counts: Vec<int> = []
    let mut last: Vec<int> = []
    let mut i: int = 0
    while i <= limit {
        sieve.push(true)
        counts.push(0)
        last.push(0 - 1)
        i += 1
    }
    let mut p: int = 2
    while p <= limit {
        if sieve[p as usize] {
            let mut m: int = p * p
            while m <= limit {
                sieve[m as usize] = false
                m += p
            }
        }
        p += 1
    }
    let mut c: int = 0
    let mut l: int = 0 - 1
    let mut k: int = 0
    while k <= limit {
        if k >= 2 && sieve[k as usize] {
            c += 1
            l = k
        }
        counts[k as usize] = c
        last[k as usize] = l
        k += 1
    }
    let mut first = true
    for line in text.lines() {
        if first {
            first = false
            continue
        }
        let t = line.trim()
        if t.len() == 0 {
            continue
        }
        let n: int = t.parse::<int>().unwrap_or(0)
        if n < 2 {
            println("0 none")
        } else {
            println("${counts[n as usize]} ${last[n as usize]}")
        }
    }
}

